```python
from urllib.parse import parse_qsl, urlencode, urlparse, urlunparse


def apply_rewrite_rules(rules, urls):
    """Applies an ordered list of rewrite rules to a list of URLs.

    For each URL, applies only the first matching rule and stops.
    Returns the rewritten URL, None if blocked, or the original URL if no rules
    match.
    """
    output_urls = []

    for url_str in urls:
        parsed = urlparse(url_str)
        matched = False

        for rule in rules:
            m_type = rule.get("match_type")
            m_val = rule.get("match_value")
            action = rule.get("action")
            action_val = rule.get("action_value")

            # 1. Check "path_prefix" match
            if m_type == "path_prefix":
                if parsed.path.startswith(m_val):
                    matched = True
                    if action == "block":
                        parsed = None
                    elif action == "strip_prefix":
                        new_path = parsed.path[len(action_val) :]
                        if not new_path:
                            new_path = "/"
                        # Rebuild URL with new path
                        parsed = parsed._replace(path=new_path)
                    break

            # 2. Check "host" match
            elif m_type == "host":
                host_matches = False
                if m_val.startswith("*."):
                    suffix = m_val[1:]  # e.g., ".example.com"
                    # Must be a strict subdomain
                    if parsed.hostname and parsed.hostname.endswith(suffix):
                        # Ensure it's not the apex domain itself
                        if len(parsed.hostname) > len(suffix):
                            host_matches = True
                else:
                    if parsed.hostname == m_val:
                        host_matches = True

                if host_matches:
                    matched = True
                    if action == "block":
                        parsed = None
                    elif action == "redirect_host":
                        # Replace netloc while preserving port if present in original or handled
                        # parsed.netloc includes host:port. We need to handle port safely.
                        port = parsed.port
                        if port:
                            new_netloc = f"{action_val}:{port}"
                        else:
                            new_netloc = action_val
                        parsed = parsed._replace(netloc=new_netloc)
                    break

            # 3. Check "query_param" match
            elif m_type == "query_param":
                query_params = parse_qsl(parsed.query, keep_blank_values=True)
                has_param = any(k == m_val for k, v in query_params)

                if has_param:
                    matched = True
                    if action == "block":
                        parsed = None
                    elif action == "add_query_param":
                        # action_val format is "key=value"
                        if "=" in action_val:
                            ak, av = action_val.split("=", 1)
                            query_params.append((ak, av))
                            new_query = urlencode(query_params)
                            parsed = parsed._replace(query=new_query)
                    break

        if not matched or parsed is None:
            output_urls.append(None if matched and parsed is None else url_str)
        else:
            output_urls.append(urlunparse(parsed))

    return output_urls
```

### Explanation of Implementation Details:
1. **URL Parsing**: We use `urlparse` to break down components (`scheme`, `netloc`, `path`, `query`, etc.) and `urlunparse` to reconstruct them after modification.
2. **Path Prefix**: Checks if `parsed.path` starts with `match_value`. If `"strip_prefix"` is used, it slices the path by `len(action_val)` and defaults empty results to `"/"`.
3. **Host Matching**: Supports exact domain matching and wildcard matching (`*.domain.com`). It ensures strict subdomain matching by verifying the host is longer than the suffix (excluding the apex domain).
4. **Query Parameters**: Uses `parse_qsl` to correctly parse query strings into a list of tuples (retaining duplicate keys if present) and appends the new parameter using `urlencode`.
5. **Blocking**: If `action == "block"`, the URL output for that iteration becomes `None` immediately, halting further rule evaluation for that URL.

